#!/usr/bin/env bash
# Run every `#print axioms` in Interval64Axioms.lean and check the results.
# Allowed axioms: propext, Classical.choice, Quot.sound, and the per-theorem
# axioms generated by `native_decide` (`..._native.native_decide.ax_*`).
# Anything else (e.g. sorryAx) is reported and makes the script exit 1.
# Handles multi-line axiom lists and `does not depend on any axioms`.
#
#   scripts/check_axioms.sh                      # core: Interval64Axioms.lean
#   scripts/check_axioms.sh DIR FILE             # another package dir / axioms file
#   NATIVE_ONLY_IN='RealFP\.Demo\.' scripts/check_axioms.sh ...
#       # native_decide axioms are BAD in theorems whose name does not match
set -euo pipefail
cd "$(dirname "$0")/.."
cd "${1:-.}"
AXFILE="${2:-Interval64Axioms.lean}"
expected=$(grep -c '^#print axioms' "$AXFILE" || true)
out=$(lake lean "$AXFILE" 2>&1)
printf '%s\n' "$out" | awk -v expected="$expected" -v native_re="${NATIVE_ONLY_IN:-}" '
  function check(entry,   name, list, n, i, a, ax) {
    name = entry; sub(/ depends on axioms:.*/, "", name); sub(/^.*'"'"'(.*)'"'"'$/, "&", name)
    list = entry; sub(/^.*depends on axioms: *\[/, "", list); sub(/\].*$/, "", list)
    n = split(list, a, ",")
    for (i = 1; i <= n; i++) {
      ax = a[i]; gsub(/^[ \t]+|[ \t]+$/, "", ax)
      if (ax == "propext" || ax == "Classical.choice" || ax == "Quot.sound") continue
      if (ax ~ /\._native\.native_decide\.ax_[0-9_]+$/) {
        if (native_re != "" && name !~ native_re) { bad++; printf "native_decide NOT ALLOWED in %s\n", name; continue }
        nd++; continue
      }
      bad++; printf "BAD AXIOM %s in %s\n", ax, name
    }
  }
  {
    line = $0; sub(/^info: [^ ]+: /, "", line)       # lake build-log prefix, if any
    if (inlist) { acc = acc " " line; if (line ~ /\]/) { check(acc); inlist = 0 }; next }
    if (line ~ /does not depend on any axioms/) { total++; next }
    if (line ~ /depends on axioms: *\[/) {
      total++; acc = line
      if (line ~ /\]/) check(acc); else inlist = 1
      next
    }
    if (line ~ /(^|[^a-z])error/) { errs++; print "ERROR LINE: " line }
  }
  END {
    printf "theorems checked by #print axioms: %d (expected %d); using native_decide axioms: %d; bad axioms: %d\n",
           total, expected, nd, bad
    if (bad > 0 || errs > 0 || total != expected) { print "AXIOM CHECK FAILED"; exit 1 }
    print "AXIOM CHECK OK (only propext, Classical.choice, Quot.sound, native_decide)"
  }'
